sp_ListarFornecedor	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarFornecedor`(p_idEmpresa INT)\nBEGIN\n\n    SELECT\n\n        idFornecedor,\n\n        NomeFantasia,\n\n        RazaoSocial,\n\n        CNPJ,\n\n        Telefone,\n\n        Email,\n\n        fAtivo,\n\n        idEmpresa\n\n    FROM Fornecedor\n\n    WHERE idEmpresa = p_idEmpresa\n\n    ORDER BY NomeFantasia;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
